int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int ret = 0;
    long timeout = *timeo_p;
    long left;

    sctp_association_hold(asoc);

    while (1) {
        if (unlikely(!asoc->active || sctp_state(asoc, CLOSED))) {
            ret = -EPIPE;
            goto out;
        }

        if (msg_len <= asoc->a_rwnd && msg_len <= asoc->sndbuf_limit) {
            *timeo_p = timeout;
            ret = 0;
            goto out;
        }

        if (!timeout) {
            ret = -EAGAIN;
            goto out;
        }

        left = sctp_wait_for_event(asoc, timeout);
        if (left < 0) {
            ret = left;
            goto out;
        }
        timeout = left;
    }

out:
