    return ret;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    long timeout = *timeo_p;
    int ret = 0;
    int err = 0;
    int old_state;

    sctp_association_hold(asoc);

    while (1) {
        if (unlikely(!asoc->base.ep || !asoc->base.ep->sock))
            goto no_room;

        if (msg_len <= asoc->sndbuf_used)
            break;

        if (timeout <= 0) {
            ret = -EAGAIN;
            goto no_room;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            goto no_room;
        }

        old_state = asoc->state;
        if (old_state == SCTP_SHUTDOWN_PENDING ||
            old_state == SCTP_SHUTDOWN_SENT) {
            ret = -EPIPE;
            goto no_room;
        }

        timeout = schedule_timeout(timeout);
        *timeo_p = timeout;
    }

    sctp_association_put(asoc);
    return 0;

no_room:
    err = ret;
    if (err == -EAGAIN || err == -EINTR)
        ret = err;
    else
        ret = -EPIPE;
    sctp_association_put(asoc);
    return ret;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int ret = 0;
    long timeout = *timeo_p;
    long wait_timeout;

    sctp_association_hold(asoc);

    while (1) {
        if (msg_len <= asoc->sndbuf_used) {
            if (timeout <= 0) {
                ret = -EAGAIN;
                break;
            }

            wait_timeout = timeout;
            if (wait_timeout > MAX_SCHEDULE_TIMEOUT)
                wait_timeout = MAX_SCHEDULE_TIMEOUT;

            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                break;
            }

            schedule_timeout(wait_timeout);
            timeout -= wait_timeout;
            continue;
        }

        if (asoc->state == SCTP_STATE_CLOSED) {
            ret = -EPIPE;
            break;
        }

        if (msg_len <= asoc->rwnd) {
            break;
        }

        if (timeout <= 0) {
            ret = -EAGAIN;
            break;
        }

        wait_timeout = timeout;
        if (wait_timeout > MAX_SCHEDULE_TIMEOUT)
            wait_timeout = MAX_SCHEDULE_TIMEOUT;

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            break;
        }

        schedule_timeout(wait_timeout);
        timeout -= wait_timeout;
    }

    sctp_association_put(asoc);
    *timeo_p = timeout;
    return ret;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int ret = 0;
    long timeout;
    int err = 0;

    sctp_association_hold(asoc);

    while (1) {
        if (msg_len <= asoc->sndbuf_available)
            break;

        timeout = *timeo_p;
        if (timeout <= 0) {
            ret = -EAGAIN;
            goto out;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            goto out;
        }

        if (asoc->state == SCTP_STATE_CLOSED) {
            ret = -EPIPE;
            goto out;
        }

        schedule_timeout_interruptible(timeout);
        *timeo_p = timeout;
    }

out:
