int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
        int ret = 0;
        long timeout = *timeo_p;
        int err = 0;
        int state;

        sctp_association_hold(asoc);

        while (1) {
                if (!atomic_read(&asoc->refcnt))
                        break;

                if (msg_len <= asoc->base.sk->sk_sndbuf - asoc->sent_queue_len)
                        break;

                if (timeout <= 0) {
                        ret = -EAGAIN;
                        goto out;
                }

                if (signal_pending(current)) {
                        err = -ERESTARTSYS;
                        goto out;
                }

                state = asoc->state;
                if (state == SCTP_STATE_CLOSED || state == SCTP_STATE_SHUTDOWN) {
                        ret = -EPIPE;
                        goto out;
                }

                timeout = schedule_timeout(timeout);
        }

        *timeo_p = timeout;
out:
        sctp_association_put(asoc);
        return ret ? ret : err;
}
